-- Maintenance contracts
create table if not exists public.contracts (
  id text primary key default gen_random_uuid()::text,
  created_at timestamptz not null default now(),
  created_by text,
  created_by_name text,
  updated_at timestamptz not null default now(),
  updated_by text,
  updated_by_name text,
  deleted_at timestamptz,
  deleted_by text,
  deleted_by_name text,
  _src text,
  _seed boolean not null default false,
  data jsonb not null default '{}'::jsonb,
  client_id text,
  site_id text,
  legacy_code text,
  name text,
  site_name text,
  service_type text default 'garden_maintenance',
  frequency text,
  visits_per_month double precision,
  monthly_value numeric(14,2),
  per_visit_rate numeric(16,6),
  status text default 'active',
  start_date date,
  end_date date,
  pause_from date,
  pause_until date,
  pause_reason text,
  preferred_days jsonb,
  preferred_time text,
  crew_id text,
  billing_status text,
  annual_increase_month integer default 3,
  salesperson text,
  notes text,
  check (deleted_at is not null or client_id is not null),
  check (deleted_at is not null or name is not null),
  check (service_type is null or service_type in ('garden_maintenance', 'garden_pool', 'pool', 'lawn', 'design', 'hardscape', 'tree', 'cleanup', 'pressure_cleaning', 'gutter', 'irrigation', 'planting', 'indoor_plants', 'other')),
  check (frequency is null or frequency in ('daily', 'three_weekly', 'twice_weekly', 'weekly', 'fortnightly', 'monthly', 'custom')),
  check (deleted_at is not null or frequency is not null),
  check (visits_per_month is null or visits_per_month >= 0),
  check (monthly_value is null or monthly_value >= 0),
  check (per_visit_rate is null or per_visit_rate >= 0),
  check (status is null or status in ('active', 'paused', 'suspended', 'left')),
  check (preferred_time is null or preferred_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  check (billing_status is null or billing_status in ('invoice_sent', 'invoice_not_sent', 'paid', 'not_paid', 'unknown')),
  check (annual_increase_month is null or annual_increase_month >= 1),
  check (annual_increase_month is null or annual_increase_month <= 12)
);
