  kind text default 'maintenance',
  crew_id text,
  crew_names text,
  start_time text,
  finish_by text,
  planned_minutes integer,
  instructions text,
  status text default 'scheduled',
  check_in_at timestamptz,
  check_out_at timestamptz,
  actual_minutes integer,
  site_check jsonb,
  photos_before jsonb,
  photos_after jsonb,
  client_signature text,
  quality_score integer,
  complaint text,
  rescheduled_from date,
  reschedule_reason text,
  geo jsonb,
  notes text,
  check (deleted_at is not null or date is not null),
  check (deleted_at is not null or site_name is not null),
  check (kind is null or kind in ('maintenance', 'project', 'quote_visit', 'callback', 'inspection')),
  check (start_time is null or start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  check (finish_by is null or finish_by ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
