  check (status is null or status in ('scheduled', 'in_progress', 'completed', 'skipped', 'no_access', 'rescheduled', 'weather_postponed', 'cancelled')),
  check (actual_minutes is null or actual_minutes >= 0),
  check (quality_score is null or quality_score >= 0),
