-- Incidents
create table if not exists public.incidents (
  id text primary key default gen_random_uuid()::text,
  created_at timestamptz not null default now(),
  created_by text,
  created_by_name text,
  updated_at timestamptz not null default now(),
  updated_by text,
  updated_by_name text,
  deleted_at timestamptz,
  deleted_by text,
  deleted_by_name text,
  _src text,
  _seed boolean not null default false,
  data jsonb not null default '{}'::jsonb,
  number text,
  date date,
  time text,
  location text,
  site_id text,
  type text,
  severity text default 'low',
  people_involved text,
  description text,
  immediate_action text,
  root_cause text,
  corrective_action text,
  investigation jsonb,
  reportable boolean,
  status text default 'open',
  photos jsonb,
  check (deleted_at is not null or date is not null),
  check (time is null or time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  check (type is null or type in ('injury', 'near_miss', 'property_damage', 'vehicle', 'equipment', 'environmental', 'security', 'complaint')),
  check (deleted_at is not null or type is not null),
  check (severity is null or severity in ('low', 'medium', 'high', 'critical')),
  check (deleted_at is not null or description is not null),
  check (status is null or status in ('open', 'investigating', 'closed'))
);
